// TH16 v1.00a Stage 2 mid-stage wave, unit th16_s2_w03.
// Source: st02.ecl.txt:962-1003 MainSub02; deps GirlC02 412-435, GirlC02_at 437-486,
// MainSub02b 1005-1011, Phantom01 1201-1221, Phantom01B/R 1223-1239, Phantom01_at 1241-1274.

const TH16_BALL2: int = 432;      // source etSprite type 5
const TH16_RING_BALL2: int = 464; // source etSprite type 7
const PHANTOM_COLOR: int = 2;
const C02_COLOR: int = 4;

const TIME_LIMIT: int = 2924;
const OPENING_BUFFER: int = 120;

// GirlC02_at EX records: ANIM a=1 (birth retreat 4*speed, applied at fire below) then
// ACCEL a=230, r=0.01 (0.02 Hard), s=-999999 => keep current bullet angle.
xformdef C02_ACCEL(gx: fx, gy: fx) {
    @230 set_gravity(gx, gy);
    set_gravity(0fx, 0fx);
}

// Phantom01_at: etAim(0,0), sprite type5/color2, etCountD lanes=1 layers={1,1,2,3},
// etSpeedD speed0={1.5,2.0,3.0,4.0} speed1={1.0,0.8,1.0,1.0}; diffI volleys={1,2,2,3};
// fire interval wait={240,240,120,50}. ANIM a=1 retreat = 4*speed along each bullet angle.
async sub phantom_shot() {
    var rank: int = global(GVAR_RANK);
    var layers: int = 1;
    var volleys: int = 1;
    var interval: int = 240;
    var s0: fx = 1.5fx;
    var s1: fx = 1.5fx;
    if rank == 1 { layers = 1; volleys = 2; interval = 240; s0 = 2.0fx; s1 = 2.0fx; }
    if rank == 2 { layers = 2; volleys = 2; interval = 120; s0 = 3.0fx; s1 = 1.0fx; }
    if rank == 3 { layers = 3; volleys = 3; interval = 50; s0 = 4.0fx; s1 = 1.0fx; }
    wait(10 + rand(60)); // wait(10 + RAND % 60)
    for v in 0..volleys {
        var a: angle = aim_player(); // one aim angle per etOn
        for q in 0..layers {
            var sp: fx = s0;
            if layers > 1 { sp = s0 + (s1 - s0) * (q as fx) / ((layers - 1) as fx); }
            _ = fire(TH16_BALL2, PHANTOM_COLOR,
                     $self_x - 4fx * sp * cos(a), $self_y - 4fx * sp * sin(a),
                     sp, a, none, none);
        }
        wait(interval);
    }
}

// Phantom01: hurtbox 28/2, hitbox 16/2; moveVel(PI/2, 0.5); moveVelTime(120, mode3,
// PI/2, 1.0); moveEllipseRel(F0, 2deg/frame, r=40, d=0, axis=ABS_ANGLE=PI/2, ratio=0).
// ratio=0 with axis PI/2 gives REL x = 40*cos(theta), y = 0.  From script time 240,
// moveVelTime(120, mode3, -PI/2, 1.0) turns 90deg -> 270deg (through 180deg).
async sub phantom(f0: angle, sway: fx, mirror: int) {
    set_invuln(65535);
    set_hurtbox(14fx);
    set_hitbox(8fx);
    spawn phantom_shot(); // @Phantom01_at() async
    // Non-Time ellipse setter computes its position immediately (theta = F0).
    move_vel_xy(0, sway * 40fx * cos(f0), 0fx, EASE_LINEAR);
    wait(1);
    var t: int = 1;
    loop {
        var sp: fx = 1fx;
        var a: angle = 90deg;
        if t <= 120 {
            var u: fx = (t as fx) / 120fx;
            sp = 0.5fx + 0.5fx * u * u * u * u; // mode3: quartic accel
        }
        if t > 240 && t <= 360 {
            var v: fx = ((t - 240) as fx) / 120fx;
            var q: angle = ((v * v * v * v * 32767fx) as int) as angle;
            // mirror flips the ABS x/angle write: source turn goes through 180deg,
            // the mirrored enemy's goes through 0deg.
            if mirror != 0 { a = 90deg - q; } else { a = 90deg + q; }
        }
        if t > 360 {
            if mirror != 0 { a = -90deg; } else { a = 270deg; }
        }
        var th1: angle = f0 + ((t * 364) as angle);
        var th0: angle = f0 + (((t - 1) * 364) as angle);
        var vx: fx = sp * cos(a) + sway * 40fx * (cos(th1) - cos(th0));
        var vy: fx = sp * sin(a);
        move_vel_xy(0, vx, vy, EASE_LINEAR);
        wait(1);
        t = t + 1;
    }
}

// GirlC02_at: etAim(0,3), sprite type7/color4, etCountD lanes={8,24,36,24} layers=1,
// etAngle(ANGLE_PLAYER, 10deg), etSpeed(0.3,1.0) => 0.3, diffI volleys={2,3,3,3},
// wait={130,130,80,60} after each etOn.
async sub girl_shot() {
    var rank: int = global(GVAR_RANK);
    var lanes: int = 8;
    var volleys: int = 2;
    var interval: int = 130;
    var acc: fx = 0.01fx;
    if rank == 1 { lanes = 24; volleys = 3; interval = 130; }
    if rank == 2 { lanes = 36; volleys = 3; interval = 80; acc = 0.02fx; }
    if rank == 3 { lanes = 24; volleys = 3; interval = 60; }
    wait(60);
    for v in 0..volleys {
        var base: angle = aim_player(); // mode3 alpha, re-read at each etOn
        for i in 0..lanes {
            var a: angle = base + (((i * 65536) / lanes) as angle);
            var gx: fx = acc * cos(a);
            var gy: fx = acc * sin(a);
            // ANIM a=1 retreat 4*0.3 = 1.2px along the bullet's own angle.
            _ = fire(TH16_RING_BALL2, C02_COLOR,
                     $self_x - 1.2fx * cos(a), $self_y - 1.2fx * sin(a),
                     0.3fx, a, C02_ACCEL(gx, gy), none);
        }
        wait(interval);
    }
}

// GirlC02: hurtbox 32/2, hitbox 24/2; moveVel(-11.25deg, 2.0);
// moveVelTime(80, mode1, keep angle, 0.1); wait 80; moveVelTime(70, mode1, 0deg, 0.3);
// wait 70; then the source idles forever (natural exit is offscreen recycling).
async sub girl(x0: fx, dir0: angle, dir1: angle) {
    set_invuln(65535);
    set_hurtbox(16fx);
    set_hitbox(12fx);
    move_vel(0, dir0, 2.0fx, EASE_LINEAR);
    move_vel(80, dir0, 0.1fx, EASE_QUAD_IN);
    spawn girl_shot(); // @GirlC02_at() async
    wait(80);
    move_vel(70, dir1, 0.3fx, EASE_QUAD_IN);
    wait(70);
    loop { wait(1000); }
}

// MainSub02b: wait(90) then two GirlC02 at (-224,240) plain / (224,240) mirrored.
async sub rest_c02() {
    wait(90);
    _ = spawn_enemy(-224fx, 240fx, 1500, 0, 0, 0, girl(-224fx, -11.25deg, 0deg));
    _ = spawn_enemy(224fx, 240fx, 1500, 0, 0, 0, girl(224fx, 191.25deg, 180deg));
}

// MainSub02: A starts 0, wait(2), $B=2 groups of nine. Group 1 waits 40 and F0=+20deg*k;
// group 2 waits 35 and F0=-20deg*k. Each step: A+=16, create B at +A and R(mirrored) at -A.
async sub pattern() {
    wait(OPENING_BUFFER); // shell buffer; source MainSub02 keeps its own wait(2) below
    wait(2);
    for g in 0..2 {
        var fstep: int = 3641; // 20deg in BAM
        var iv: int = 40;
        if g == 1 { fstep = -3641; iv = 35; }
        for k in 0..9 {
            var ax: fx = ((k + 1) * 16) as fx;
            var ph: angle = ((k * fstep) as angle);
            _ = spawn_enemy(ax, -24fx, 100, 0, 0, 0, phantom(ph, 1fx, 0));
            _ = spawn_enemy(-ax, -24fx, 100, 0, 0, 0, phantom(ph, -1fx, 1));
            wait(iv);
        }
    }
    spawn rest_c02(); // @MainSub02b() async
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
